// ADR 0025's vocabulary as rich fashion illustrations, all on one 64 x 64 viewBox: 90 cut
// drawings (49 women's `-f`, 41 men's `-m`, accessories included), the six category glyphs, and
// fifteen base drawings that draw no catalogue type and that nothing draws any more. A drawing
// is a list of groups painted in order. Each group's `outline` is filled with one colour role
// and stroked with the ink edge; its `parts` are clipped to that outline, so light, folds and
// seams never spill past the edge. `garment-paint.ts` paints them, lights them and owns the
// level-of-detail rule.
//
// Part kinds: `fs` shade, `fl` light, `fk` dark trim, `fa` material, `fas` material shade,
// `fm` main (a panel over another group), `fh` hardware; lines: `D` construction (ink, or the
// tone colour where ink sits under 3:1 on the fill), `Dh` zip in the hardware colour, `T` tone
// line, `Ta` tone line on the material, `S` stitch, `Sh` stitch in the hardware colour, `Sa`
// stitch on the material, `L` a highlight where the light catches a fold or a ridge, `Q` a
// quilt seam that pulls the fill into a soft valley. Folds are `fs` slivers painted first,
// under the construction. Outlines follow the cut of the garment (rounded shoulders, tapering
// sleeves, curved hems, a trouser break, a shoe's heel and instep).
//
// Bounds are measured from the outlines, stroke excluded, and are what ADR 0025's composition
// rule reads; silhouettes.test.mjs recomputes them from the outlines.
export type SilhouetteFillRole = 'main' | 'shade' | 'toneLine' | 'darkTrim' | 'material' | 'hardware';
export type SilhouettePartKind =
  | 'fs' | 'fl' | 'fk' | 'fa' | 'fas' | 'fm' | 'fh'
  | 'D' | 'Dh' | 'T' | 'Ta' | 'S' | 'Sh' | 'Sa' | 'L' | 'Q';

export type SilhouetteGroup = Readonly<{
  outline: string;
  fill: SilhouetteFillRole;
  parts: readonly (readonly [SilhouettePartKind, string])[];
  /** A group drawn without the ink edge (the scarf's fringe). */
  stroked?: false;
}>;

/**
 * The cloth a drawing is made of, for its rendering: knit columns, denim and suiting twills,
 * straw's cross-weave, and the highlight band of leather, nylon and rubber. A drawing
 * without one (jersey, cotton poplin, a category glyph) is lit but unwoven.
 */
export type SilhouetteCloth = 'knit' | 'denim' | 'twill' | 'straw' | 'sheen';

export type Silhouette = Readonly<{
  id: string;
  viewBox: 64;
  cloth?: SilhouetteCloth;
  groups: readonly SilhouetteGroup[];
  bounds: Readonly<{ x: number; y: number; width: number; height: number }>;
}>;

